GLOBO_FS:
precision highp float;
varying vec2 vPos;
uniform sampler2D uTex;     // día: Blue Marble con batimetría
uniform sampler2D uNoche;   // noche: luces de ciudad VIIRS (Black Marble)
uniform sampler2D uNubes;   // nubosidad real, en escala de grises
uniform float uLon, uLat, uAspect, uNubOff;
const float PI=3.14159265359;
void main(){
  /* Coordenadas dentro del disco: el aspecto corrige que el canvas no sea cuadrado,
     porque si no la Tierra saldría con forma de huevo. */
  vec2 d=vec2(vPos.x*uAspect, vPos.y)/0.87;
  float r2=dot(d,d);
  if(r2>1.0){
    /* Fuera de la esfera: halo de atmósfera que se apaga rápido. */
    float rr=sqrt(r2);
    float a=rr<1.18 ? pow(1.0-(rr-1.0)/0.18,2.0)*0.5 : 0.0;
    if(a<=0.001) discard;
    gl_FragColor=vec4(0.35,0.59,0.88,a);
    return;
  }
  float dz=sqrt(1.0-r2);
  float cx=cos(uLat), sx=sin(uLat), cy=cos(uLon), sy=sin(uLon);
  /* Inversa de gl3(): se deshace primero el giro de latitud y luego el de longitud. */
  float y1= d.y*cx + dz*sx;
  float z1=-d.y*sx + dz*cx;
  float x2= d.x*cy + z1*sy;
  float z2=-d.x*sy + z1*cy;
  float lat=asin(clamp(y1,-1.0,1.0));
  float lon=atan(x2,z2);
  vec2 uv=vec2(lon/(2.0*PI)+0.5, 0.5-lat/PI);
  /* Sol fijo arriba-izquierda y algo por delante: da relieve y deja un terminador
     suave que es lo que hace que se lea como ESFERA y no como disco. */
  vec3 n=vec3(d.x,d.y,dz);
  /* El sol va MUY oblicuo a propósito. Con la componente z alta (0.72) quedaba casi
     de frente, todo el disco visible iluminado y la cara nocturna escondida por
     detrás: las luces de ciudad no se veían nunca. Bajándola a 0.28 el terminador
     cruza el disco y siempre hay un trozo de planeta de noche, encendido. */
  vec3 sol=normalize(vec3(-0.62,0.44,0.28));
  float cara=dot(n,sol);
  float dif=max(cara,0.0);

  vec3 dia=texture2D(uTex,uv).rgb*(0.42+0.72*dif);
  /* La cara nocturna no es negra: son las luces de ciudad de verdad, medidas por el
     VIIRS. Es lo que convierte el globo en un planeta habitado — se distingue Europa,
     el este de EE.UU., el valle del Nilo, la costa japonesa. */
  vec3 noche=texture2D(uNoche,uv).rgb*1.35;

  /* El terminador se cruza con smoothstep y no con un corte: en la Tierra real el
     amanecer no es una línea, es una franja de unos cientos de kilómetros. */
  float t=smoothstep(-0.14,0.30,cara);
  vec3 col=mix(noche,dia,t);

  /* Nubes reales, desplazadas en longitud para que giren un poco más despacio que el
     planeta. Se iluminan como el terreno y casi desaparecen de noche, igual que pasa
     de verdad. */
  float nub=texture2D(uNubes,vec2(uv.x+uNubOff,uv.y)).r;
  col=mix(col,vec3(1.0,0.99,0.97)*(0.30+0.80*dif),nub*0.72*max(t,0.10));

  /* Realce de borde: la atmósfera vista de canto. */
  col+=pow(1.0-dz,3.0)*vec3(0.35,0.55,0.85)*0.42;
  gl_FragColor=vec4(col,1.0);
}

GLOBO_VS:
attribute vec2 aPos;
varying vec2 vPos;
void main(){ vPos=aPos; gl_Position=vec4(aPos,0.0,1.0); }
